#!/usr/bin/env python3
"""
Test all models listed in a JSON config file against an OpenAI-compatible API.

Usage:
  python test_models.py path/to/models.json

Accepted JSON formats:
  ["model-a", "model-b"]
  {"models": ["model-a", "model-b"]}
"""

import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECS = 30


def load_models(path: str):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, list):
        return data

    if isinstance(data, dict):
        for key in ("models", "model_list", "model_names"):
            if key in data and isinstance(data[key], list):
                return data[key]

    raise ValueError("Unsupported JSON format. Use a list or {'models': [...]}.")


def http_post_json(url: str, payload: dict, timeout: int):
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=body,
        method="POST",
        headers={"Content-Type": "application/json"},
    )

    start = time.perf_counter()
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read()
            latency = time.perf_counter() - start
            return resp.getcode(), raw, latency, None
    except urllib.error.HTTPError as e:
        raw = e.read()
        latency = time.perf_counter() - start
        return e.code, raw, latency, str(e)
    except Exception as e:
        latency = time.perf_counter() - start
        return None, None, latency, repr(e)


def parse_openai_chat_response(raw_bytes):
    if not raw_bytes:
        return None, "empty response body"

    try:
        data = json.loads(raw_bytes.decode("utf-8"))
    except Exception:
        return None, "non-JSON response"

    if isinstance(data, dict) and "error" in data:
        err = data["error"]
        if isinstance(err, dict):
            return None, err.get("message") or json.dumps(err)
        return None, str(err)

    try:
        choice0 = data["choices"][0]
        if isinstance(choice0, dict):
            if "message" in choice0 and isinstance(choice0["message"], dict):
                return choice0["message"].get("content", ""), None
            if "text" in choice0:
                return choice0.get("text", ""), None
    except Exception:
        pass

    return None, "missing choices[0].message.content"


def is_temperature_unsupported(err_text: str):
    if not err_text:
        return False
    low = err_text.lower()
    if "temperature" not in low:
        return False
    keywords = (
        "unsupported",
        "unknown",
        "unexpected",
        "unrecognized",
        "not allowed",
        "not permitted",
        "extra",
        "invalid",
    )
    return any(k in low for k in keywords)


def preview(s: str, n: int = 50):
    s = (s or "").replace("\r", " ").replace("\n", " ").strip()
    return s[:n]


def test_model(model_name: str):
    base_payload = {
        "model": model_name,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
    }

    # First try including temperature.
    payload = dict(base_payload)
    payload["temperature"] = 0

    code, raw, latency, transport_err = http_post_json(API_URL, payload, TIMEOUT_SECS)
    content, parse_err = parse_openai_chat_response(raw) if raw else (None, transport_err or "no response")

    # If success, evaluate.
    if code is not None and 200 <= code < 300 and parse_err is None:
        text = (content or "").strip()
        status = "PASS" if text == "OK" else "FAIL"
        return {
            "Model": model_name,
            "Status": status,
            "Latency": latency,
            "Response": preview(text),
        }

    # If it looks like temperature is unsupported, retry without temperature.
    combined_err = parse_err or transport_err or ""
    if is_temperature_unsupported(combined_err):
        code2, raw2, latency2, transport_err2 = http_post_json(API_URL, base_payload, TIMEOUT_SECS)
        content2, parse_err2 = parse_openai_chat_response(raw2) if raw2 else (None, transport_err2 or "no response")

        if code2 is not None and 200 <= code2 < 300 and parse_err2 is None:
            text2 = (content2 or "").strip()
            status2 = "PASS" if text2 == "OK" else "FAIL"
            return {
                "Model": model_name,
                "Status": status2,
                "Latency": latency2,
                "Response": preview(text2),
            }

        err_msg = parse_err2 or transport_err2 or combined_err
        return {
            "Model": model_name,
            "Status": "FAIL",
            "Latency": latency2,
            "Response": preview(err_msg),
        }

    # Otherwise, fail with whatever we got.
    return {
        "Model": model_name,
        "Status": "FAIL",
        "Latency": latency,
        "Response": preview(combined_err or (content or "")),
    }


def print_table(rows):
    headers = ["Model", "Status", "Latency", "Response"]

    latency_strs = [f"{r['Latency']:.2f}" for r in rows]
    models = [str(r["Model"]) for r in rows]
    statuses = [str(r["Status"]) for r in rows]
    responses = [str(r["Response"]) for r in rows]

    col_model = max(len(headers[0]), *(len(x) for x in models)) if rows else len(headers[0])
    col_status = max(len(headers[1]), *(len(x) for x in statuses)) if rows else len(headers[1])
    col_latency = max(len(headers[2]), *(len(x) for x in latency_strs)) if rows else len(headers[2])
    col_resp = max(len(headers[3]), *(len(x) for x in responses)) if rows else len(headers[3])

    fmt = f"{{:<{col_model}}}  {{:<{col_status}}}  {{:>{col_latency}}}  {{:<{col_resp}}}"
    sep = "-" * (col_model + 2 + col_status + 2 + col_latency + 2 + col_resp)

    print(fmt.format(*headers))
    print(sep)
    for r, lat_s in zip(rows, latency_strs):
        print(fmt.format(r["Model"], r["Status"], lat_s, r["Response"]))


def main():
    if len(sys.argv) != 2:
        print("Usage: python test_models.py path/to/models.json", file=sys.stderr)
        return 2

    try:
        models = load_models(sys.argv[1])
    except Exception as e:
        print(f"Error loading models: {e}", file=sys.stderr)
        return 2

    results = []
    for m in models:
        results.append(test_model(str(m)))

    print_table(results)

    total = len(results)
    working = sum(1 for r in results if r["Status"] == "PASS")
    failed = total - working
    print(f"\nTotal: {total} models | ✅ {working} working | ❌ {failed} failed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
